using Microsoft.EntityFrameworkCore;using ProMaxx2.QA.Application.Releases;using ProMaxx2.QA.Domain.Releases;using ProMaxx2.QA.Application.Common;
namespace ProMaxx2.QA.Infrastructure.Persistence;
public sealed class ReleaseRepository(QaDbContext db,ProjectAccessContext projectCtx):IReleaseRepository
{
 public async Task<IReadOnlyList<ReleaseDto>>ListAsync(Guid? projectId,CancellationToken ct){var q=db.Releases.AsNoTracking().AsQueryable();if(projectId.HasValue)q=q.Where(x=>x.ProjectId==projectId);else if(projectCtx.AllowedProjectIds.Length>0)q=q.Where(x=>projectCtx.AllowedProjectIds.Contains(x.ProjectId));else q=q.Where(_=>false);return await q.OrderByDescending(x=>x.CreatedAt).Select(x=>new ReleaseDto(x.ReleaseId,x.ProjectId,x.ReleaseCode,x.Version,x.ReleaseType,x.Scope,x.PlannedReleaseDate,x.ActualReleaseDate,x.Status,x.ReleaseOwnerUserId,x.CreatedAt)).ToListAsync(ct);}
 public Task<ReleaseDto?>GetAsync(Guid id,CancellationToken ct)=>db.Releases.AsNoTracking().Where(x=>x.ReleaseId==id).Select(x=>new ReleaseDto(x.ReleaseId,x.ProjectId,x.ReleaseCode,x.Version,x.ReleaseType,x.Scope,x.PlannedReleaseDate,x.ActualReleaseDate,x.Status,x.ReleaseOwnerUserId,x.CreatedAt)).SingleOrDefaultAsync(ct);public Task<Release?>FindAsync(Guid id,CancellationToken ct)=>db.Releases.SingleOrDefaultAsync(x=>x.ReleaseId==id,ct);public Task<bool>CodeExistsAsync(Guid projectId,string code,CancellationToken ct)=>db.Releases.AnyAsync(x=>x.ProjectId==projectId&&x.ReleaseCode==code,ct);public Task AddAsync(Release e,CancellationToken ct)=>db.Releases.AddAsync(e,ct).AsTask();
 public async Task<IReadOnlyList<BuildDto>>ListBuildsAsync(Guid releaseId,CancellationToken ct)=>await db.Builds.AsNoTracking().Where(x=>x.ReleaseId==releaseId).OrderByDescending(x=>x.BuildDate).Select(x=>new BuildDto(x.BuildId,x.ReleaseId,x.BuildNumber,x.ApplicationVersion,x.PackageVersion,x.CommitReference,x.BuildDate,x.ChangeNotes,x.KnownIssues,x.IsReleaseCandidate,x.IsActive,x.Status)).ToListAsync(ct);public Task<BuildDto?>GetBuildAsync(Guid id,CancellationToken ct)=>db.Builds.AsNoTracking().Where(x=>x.BuildId==id).Select(x=>new BuildDto(x.BuildId,x.ReleaseId,x.BuildNumber,x.ApplicationVersion,x.PackageVersion,x.CommitReference,x.BuildDate,x.ChangeNotes,x.KnownIssues,x.IsReleaseCandidate,x.IsActive,x.Status)).SingleOrDefaultAsync(ct);public Task<Build?>FindBuildAsync(Guid id,CancellationToken ct)=>db.Builds.SingleOrDefaultAsync(x=>x.BuildId==id,ct);public Task<int>CountBlockedAsync(Guid buildId,CancellationToken ct)=>db.TestCycleCases.CountAsync(x=>x.Cycle.BuildId==buildId&&x.CurrentStatus=="Blocked",ct);public Task<bool>BuildNumberExistsAsync(Guid releaseId,string number,CancellationToken ct)=>db.Builds.AnyAsync(x=>x.ReleaseId==releaseId&&x.BuildNumber==number,ct);public Task AddBuildAsync(Build e,CancellationToken ct)=>db.Builds.AddAsync(e,ct).AsTask();public Task SaveChangesAsync(CancellationToken ct)=>db.SaveChangesAsync(ct);
}
